import openpyxl
p_in='2_382-29_answer_template_9647_input.xlsx'
p_filled='2_382-29_answer_template_9647_input_filled.xlsx'
wbi=openpyxl.load_workbook(p_in, data_only=False)
wbf=openpyxl.load_workbook(p_filled, data_only=False)

def borderkey(cell):
    b=cell.border
    sides=[]
    for s in [b.left,b.right,b.top,b.bottom,b.diagonal]:
        sides.append((s.style, getattr(s.color,'type',None), getattr(s.color,'theme',None), getattr(s.color,'rgb',None)))
    return tuple(sides)

def fontkey(cell):
    f=cell.font
    return (f.name, f.sz, f.bold, f.italic, f.underline, f.strike, f.vertAlign, f.outline, f.shadow,
            getattr(f.color,'type',None), getattr(f.color,'theme',None), getattr(f.color,'rgb',None))

def alignkey(cell):
    a=cell.alignment
    return (a.horizontal,a.vertical,a.text_rotation,a.wrap_text,a.shrink_to_fit,a.indent,a.relativeIndent,a.justifyLastLine,a.readingOrder)

total_bad=0
for sn in wbi.sheetnames:
    wsi=wbi[sn]; wsf=wbf[sn]
    bad=0
    for r in range(1, max(wsi.max_row,wsf.max_row)+1):
        for c in range(1, max(wsi.max_column,wsf.max_column)+1):
            ci=wsi.cell(row=r,column=c); cf=wsf.cell(row=r,column=c)
            if borderkey(ci)!=borderkey(cf) or fontkey(ci)!=fontkey(cf) or alignkey(ci)!=alignkey(cf) or ci.number_format!=cf.number_format:
                bad+=1
                if bad<5:
                    print('STYLE DIFF', sn, ci.coordinate)
    print(sn, 'style diffs', bad)
    total_bad+=bad
print('TOTAL style diffs', total_bad)
# merged cells comparison
for sn in wbi.sheetnames:
    print(sn, 'merged in', sorted(str(x) for x in wbi[sn].merged_cells.ranges), 'merged filled', sorted(str(x) for x in wbf[sn].merged_cells.ranges))
